var minJumps = function(arr) {
    const n = arr.length;
    const map = new Map();

    for (let i = 0; i < n; i++) {
        if (!map.has(arr[i])) {
            map.set(arr[i], []);
        }
        map.get(arr[i]).push(i);
    }

    let stack = [0];
    const seen = Array(n).fill(false);
    seen[0] = true;
    let steps = 0;

    while (stack.length > 0) {
        const next = [];

        for (const pos of stack) {
            if (pos === n - 1) {
                return steps;
            }

            const mapArr = map.get(arr[pos]);
            if (mapArr) {
                for (const con of mapArr) {
                    if (con !== pos && !seen[con]) {
                        seen[con] = true;
                        next.push(con);
                    }
                }
                map.set(arr[pos], []);
            }

            const back = pos - 1;
            if (back >= 0 && !seen[back]) {
                seen[back] = true;
                next.push(back);
            }

            const forw = pos + 1;
            if (forw < n && !seen[forw]) {
                seen[forw] = true;
                next.push(forw);
            }
        }

        stack = next;
        steps++;
